INSERT INTO "RecordDefinition" ("recordKey","engine","mount","pageFile","docCode","title","docRevisionStart","jobInfoGroup","clientHook","primaryBatchField","extraBatchFields","extraJson","version","updatedAt") VALUES ('production-information-nrcs','form-record','#frRoot','Production-Information-NRCS-(Canning)-production-information-nrcs.html','Production Information NRCS (Canning)','Production Information NRCS (Canning)',1,NULL,NULL,'jobNo',ARRAY[]::text[],'{"batchField":"jobNo","stage":"nrcs-canning","listColumns":["productionCode","nrcsAgCode"],"instructions":[{"label":"How to fill this in","text":"Choose the job number first — each row in the records table below then picks from the records actually filed against that job, linking the exact submission rather than just the record type. With no job number chosen the picker falls back to the full Master Index list. When a row picks a Cans Produced (REC 7.2.7) submission, its production code, NRCS AG code, and product description fill in automatically."},{"label":"Submitting this record","text":"Every row in the records table below must be attached (a specific record picked, not just a record type) and show \"Verified\" before this NRCS record can be submitted. You can still save a draft at any point while records are still being filed or verified elsewhere."}]}'::jsonb,COALESCE((SELECT "version" FROM _pv WHERE "recordKey"='production-information-nrcs'),0)+1,now());
