INSERT INTO "RecordDefinition" ("recordKey","engine","mount","pageFile","docCode","title","docRevisionStart","jobInfoGroup","clientHook","primaryBatchField","extraBatchFields","extraJson","version","updatedAt") VALUES ('ph-verification','monitoring-log','#mlRoot','REC-7.10.2-ph-verification.html','REC 7.10.2','pH Verification',8,NULL,NULL,NULL,ARRAY[]::text[],'{"instructions":[{"label":"Weekly","text":"Measure 20ml of buffer pH 4, insert probe, take reading. Repeat with buffer pH 7 and pH 10. Meter should read within 3.9–4.1 (buffer 4.01), 6.9–7.1 (buffer 7.01), 9.9–10.1 (buffer 10.01). If outside range, record the deviation and repeat the monthly calibration; if still out of spec, record it and report the issue."},{"label":"Monthly","text":"Measure 20ml of buffer pH 4, 7 and 10, click CAL on the pH meter and follow the instructions. Record that the calibration was done successfully."}],"primaryLogTitle":"Weekly pH check","specFields":[{"key":"buffer4","label":"pH buffer 4.01 reading","min":3.9,"max":4.1},{"key":"buffer7","label":"pH buffer 7.01 reading","min":6.9,"max":7.1},{"key":"buffer10","label":"pH buffer 10.01 reading","min":9.9,"max":10.1}],"deviationLabel":"Equipment accurate","deviationPolarity":"accurate","secondaryLog":{"key":"monthly-calibration","title":"Monthly calibration","deviationLabel":"Calibrated","deviationPolarity":"accurate","entryFields":[{"key":"date","label":"Date","type":"date","required":true},{"key":"calibrationPerformed","label":"Calibration performed","type":"yesno"},{"key":"comments","label":"Comments","type":"textarea"},{"key":"checkedBy","label":"Checked by","type":"text","required":true}]}}'::jsonb,COALESCE((SELECT "version" FROM _pv WHERE "recordKey"='ph-verification'),0)+1,now());
