INSERT INTO "RecordDefinition" ("recordKey","engine","mount","pageFile","docCode","title","docRevisionStart","jobInfoGroup","clientHook","primaryBatchField","extraBatchFields","extraJson","version","updatedAt") VALUES ('thermometer-verification','monitoring-log','#mlRoot','REC-7.10.3-thermometer-verification.html','REC 7.10.3','Thermometer Verification',6,NULL,NULL,NULL,ARRAY[]::text[],'{"instructions":[{"label":"Verify thermometer accuracy","text":"Verification must be done using a standard reference thermometer and a test thermometer. Deviation should not be larger than 0.5°C — if it is, complete REC 7.10.4 to add a correction factor."},{"label":"Cold verification (0–5°C)","text":"Crush ice, fill half a jar, top up with water and stir. Insert reference probe and test thermometer, wait to stabilise, then record."},{"label":"Hot verification (85–95°C)","text":"Boil water, insert reference probe and test thermometer, wait to stabilise and record. If the reading exceeds the specified limits, a corrective action must be recorded."},{"label":"Frequency","text":"Weekly."}],"relatedLinks":[{"label":"If deviation exceeds 0.5°C, complete Thermometer Correction Factors to add a correction factor.","href":"REC-7.10.4-thermometer-correction-factors.html"}],"showVerificationStrip":false,"specFields":[{"key":"coldRange","label":"Cold water reference/test reading","unit":"°C","min":0,"max":5},{"key":"hotRange","label":"Hot water reference/test reading","unit":"°C","min":85,"max":95},{"key":"diffTolerance","label":"Reference vs test deviation","unit":"°C","min":-0.5,"max":0.5}],"deviationLabel":"Equipment accurate","deviationPolarity":"accurate"}'::jsonb,COALESCE((SELECT "version" FROM _pv WHERE "recordKey"='thermometer-verification'),0)+1,now());
