INSERT INTO "RecordDefinition" ("recordKey","engine","mount","pageFile","docCode","title","docRevisionStart","jobInfoGroup","clientHook","primaryBatchField","extraBatchFields","extraJson","version","updatedAt") VALUES ('thermometer-correction-factors','monitoring-log','#mlRoot','REC-7.10.4-thermometer-correction-factors.html','REC 7.10.4','Thermometer Correction Factors',2,NULL,NULL,NULL,ARRAY[]::text[],'{"instructions":[{"label":"Verify thermometer accuracy","text":"Verification must be done using a standard reference thermometer or master thermometer calibrated by a SANAS accredited authority."},{"label":"How to establish correction factors","text":"Place the probes in one container filled with water and allow the thermometer to read for 2 minutes, then record the findings."},{"label":"Tolerance","text":"Readings should not exceed a difference of 0.5°C. If exceeded, report the thermometer and add the correction factor."},{"label":"Frequency","text":"Weekly."}],"specFields":[{"key":"diffTolerance","label":"Reference vs test difference","unit":"°C","min":-0.5,"max":0.5}],"deviationLabel":"Within tolerance","deviationPolarity":"accurate"}'::jsonb,COALESCE((SELECT "version" FROM _pv WHERE "recordKey"='thermometer-correction-factors'),0)+1,now());
