INSERT INTO "RecordDefinition" ("recordKey","engine","mount","pageFile","docCode","title","docRevisionStart","jobInfoGroup","clientHook","primaryBatchField","extraBatchFields","extraJson","version","updatedAt") VALUES ('traceability-mock-recall-canned-braised-abalone','form-record','#frRoot','REC-8.1.6-a-traceability-mock-recall-canned-braised-abalone.html','REC 8.1.6a','Traceability & Mock Recall Checklist for Canned Braised Abalone',4,NULL,NULL,'jobNo',ARRAY[]::text[],'{"batchField":"jobNo","stage":"recall-braised","listColumns":["date","agCode","jobNo"],"instructions":[{"label":"How to fill this in","text":"Choose the job number first — each roster row then picks from the records actually filed against that job, linking the exact submission rather than just the record type. With no job number chosen the picker falls back to the full Master Index list."},{"label":"Records not traced by job number","text":"Cleaning (REC 7.6.1, 7.6.2), Staff Hygiene (REC 7.6.7), Glass & Plastic (REC 7.7.2) and Utensil Issue (REC 7.7.4) are daily, weekly or per-shift records covering many jobs at once, so they are deliberately NOT filed against a job number and will not appear in the picker. Retrieve them by DATE RANGE for the production dates of this job and record them as Master Index picks."}]}'::jsonb,COALESCE((SELECT "version" FROM _pv WHERE "recordKey"='traceability-mock-recall-canned-braised-abalone'),0)+1,now());
